bruts = ["77 123 45 67", "+221 76-555-12-12", "78.900.00.11", "+22170 111 22 33"]

def nettoyer_tel(tel):
    for c in (" ", ".", "-"):
        tel = tel.replace(c, "")
    if tel.startswith("+221"):
        tel = tel[4:]
    return tel

resultat = [nettoyer_tel(t) for t in bruts]

paniers = [12500, 8300, 55540, 4860, 67010, 23000]

def resume(valeurs):
    return {
        "min": min(valeurs),
        "max": max(valeurs),
        "moyenne": round(sum(valeurs) / len(valeurs), 2),
        "n": len(valeurs),
    }

resultat = resume(paniers)

